system_a_kql:
let TimeRange = 3d;
let FirstSeenProcesses = 
    SecurityEvent
    | where TimeGenerated >= ago(TimeRange)
    | summarize FirstSeen=min(TimeGenerated) by ProcessName=ActingProcessName, DvcHostname;
let ProcessCounts = 
    SecurityEvent
    | where TimeGenerated >= ago(TimeRange)
    | summarize ProcessRunCount=count() by ProcessName=ActingProcessName;
FirstSeenProcesses
| join kind=inner (ProcessCounts) on ProcessName
| order by ProcessRunCount asc, FirstSeen asc
| project FirstSeen, DvcHostname, ProcessName, ProcessRunCount

let lookback = 3d;
let percentile_threshold = 5;
let exclude_patterns = dynamic(@'["^msiexec.*", "^setup.*", "^install.*", "^temp.*", "^tmp.*", "^random.*"]');
DeviceProcessEvents
| where TimeGenerated >= ago(lookback)
| where not(ActingProcessName matches regex strcat("(?i)", array_strcat(exclude_patterns, "|")))
| summarize ExecutionCount = count() by ActingProcessName
| summarize PercentileValue = percentile(ExecutionCount, percentile_threshold)
| where ExecutionCount <= PercentileValue
| project ActingProcessName, ExecutionCount

