system_a_kql:
let BaselineStart = ago(15d);
let BaselineEnd = ago(1d);
let RecentStart = ago(1d);
let RecentEnd = now();
let PrivateIpRange = (ip: string) {
    // RFC1918 private IP ranges
    (ip startswith "10.") or (ip startswith "172.") or (ip startswith "192.168.")
};
let SmbPorts = dynamic([139, 445]);
NetworkSession
| where SrcPortNumber in (SmbPorts) and PrivateIpRange(SrcIpAddr)
| extend TimeBin = bin(TimeGenerated, 1d)
| summarize ConnCount = count() by SrcIpAddr, SrcPortNumber, TimeBin
| where TimeBin >= BaselineStart and TimeBin < BaselineEnd
| summarize BaselineAvg = avg(ConnCount) by SrcIpAddr, SrcPortNumber
| join kind=inner (
    NetworkSession
    | where SrcPortNumber in (SmbPorts) and PrivateIpRange(SrcIpAddr)
    | where TimeGenerated >= RecentStart and TimeGenerated < RecentEnd
    | summarize RecentCount = count() by SrcIpAddr, SrcPortNumber
) on SrcIpAddr, SrcPortNumber
| where RecentCount > BaselineAvg + 50

let TimeWindow = 5m;
let UserAgentThreshold = 3;
web_session
| summarize UserAgentCount=dcount(HttpUserAgent), UserAgents=make_set(HttpUserAgent, 10) by SrcIpAddr, bin(TimeGenerated, TimeWindow)
| where UserAgentCount > UserAgentThreshold
